def transform(grid):
    from collections import Counter, deque

    if not grid:
        return grid

    rows, cols = len(grid), len(grid[0])

    # Find background color (most common)
    all_values = []
    for r in range(rows):
        for c in range(cols):
            all_values.append(grid[r][c])

    background = min(set(all_values), key=lambda x: all_values.count(x))

    # Find markers (isolated non-background pixels)
    markers = []
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != background:
                has_neighbor = False
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == val:
                            has_neighbor = True
                            break
                if not has_neighbor:
                    markers.append((r, c, val))

    # Find connected blocks (excluding markers)
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    new_grid = [[0 for _ in range(cols)] for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background and not visited[r][c]:
                # This is a block (not a marker since markers are isolated)
                block = []
                block_val = grid[r][c]

                queue = deque([(r, c)])
                visited[r][c] = True

                while queue:
                    cr, cc = queue.popleft()
                    block.append((cr, cc))

                    for dr, dc in directions:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == block_val:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                # Get block column range
                min_c = min(cc for cr, cc in block)
                max_c = max(cc for cr, cc in block)

                # Find matching marker (highest column index within block's column range)
                best_marker_val = block_val

                for mr, mc, mv in markers:
                    if min_c <= mc <= max_c:
                        best_marker_val = mv

                # Color the entire block
                for cr, cc in block:
                    new_grid[cr][cc] = best_marker_val

    # Copy markers to output
    for mr, mc, mv in markers:
        new_grid[mr][mc] = mv

    # Fill background cells that weren't covered
    for r in range(rows):
        for c in range(cols):
            if new_grid[r][c] == 0:
                new_grid[r][c] = background

    return new_grid


